const tutorias = $('Leer Tutorias').all().map(i => i.json).filter(t => t && t.id_tutoria);
const estudiantesRaw = $('Leer Estudiantes').all().map(i => i.json).filter(e => e && e.id_estudiante);
const tutoresRaw = $('Leer Tutores').all().map(i => i.json).filter(t => t && t.id_tutor);
const materiasRaw = $('Leer Materias').all().map(i => i.json).filter(m => m && m.id_materia);
const calificaciones = $('Leer Calificaciones').all().map(i => i.json).filter(c => c && c.id_tutoria);

const dedupe = (arr, key) => { const seen = new Set(); return arr.filter(x => { const k = String(x[key]); if (seen.has(k)) return false; seen.add(k); return true; }); };
const estudiantes = dedupe(estudiantesRaw, 'id_estudiante');
const tutores = dedupe(tutoresRaw, 'id_tutor');
const materias = dedupe(materiasRaw, 'id_materia');

const LF = String.fromCharCode(10);

const esManual = $execution.mode === 'manual';
let inicioSemana, finSemana, tutoriasSemana;
let parseFecha, enSemana;
parseFecha = f => { try { const p = String(f || '').split('/'); if (p.length < 3) return null; const d = new Date(p[2] + '-' + p[1].padStart(2,'0') + '-' + p[0].padStart(2,'0') + 'T12:00:00'); return isNaN(d.getTime()) ? null : d; } catch (e) { return null; } };
if (esManual) {
  inicioSemana = $now.startOf('day');
  finSemana = $now.endOf('day');
  tutoriasSemana = tutorias;
} else {
  inicioSemana = $now.minus({ days: $now.weekday - 1 }).startOf('day');
  finSemana = inicioSemana.plus({ days: 6 }).endOf('day');
  const iniJS = inicioSemana.toJSDate();
  const finJS = finSemana.toJSDate();
  enSemana = t => { const d = parseFecha(t.fecha); return d && d >= iniJS && d <= finJS; };
  tutoriasSemana = tutorias.filter(enSemana);
}
const tituloReporte = esManual ? 'Reporte Actual' : 'Reporte Semanal';
const subtituloPeriodo = esManual
  ? '<strong>Corte:</strong> ' + $now.toFormat('dd/MM/yyyy HH:mm') + ' (todos los registros)'
  : '<strong>Semana:</strong> ' + inicioSemana.toFormat('dd/MM/yyyy') + ' al ' + finSemana.toFormat('dd/MM/yyyy');

const estadoDe = t => String(t.estado || 'Solicitada');
const sinTutor = t => !t.id_tutor || String(t.id_tutor).trim() === '';
const calDe = id => calificaciones.filter(c => String(c.id_tutor) === String(id));
const promDe = id => { const cs = calDe(id); return cs.length ? (cs.reduce((a, c) => a + Number(c.valoracion || 0), 0) / cs.length) : null; };
const fmtProm = v => v === null ? '—' : v.toFixed(2);

const porTutor = tutores.map(t => {
  const ts = tutoriasSemana.filter(x => String(x.id_tutor) === String(t.id_tutor));
  const prom = promDe(t.id_tutor);
  return { id: t.id_tutor, nombre: t.nombre, materias: t.materias || '', solicitadas: ts.filter(x => estadoDe(x) === 'Solicitada').length, asignadas: ts.filter(x => estadoDe(x) === 'Asignada').length, enCurso: ts.filter(x => estadoDe(x) === 'En curso').length, finalizadas: ts.filter(x => estadoDe(x) === 'Finalizada').length, canceladas: ts.filter(x => estadoDe(x) === 'Cancelada').length, prom, total: ts.length };
});

const ranking = [...porTutor].sort((a, b) => {
  const sa = (a.prom === null ? 0 : a.prom * 2) + a.finalizadas - a.canceladas;
  const sb = (b.prom === null ? 0 : b.prom * 2) + b.finalizadas - b.canceladas;
  return sb - sa;
});

const totalSol = tutoriasSemana.length;
const totAsig = tutoriasSemana.filter(t => estadoDe(t) === 'Asignada').length;
const totEnCurso = tutoriasSemana.filter(t => estadoDe(t) === 'En curso').length;
const totFin = tutoriasSemana.filter(t => estadoDe(t) === 'Finalizada').length;
const totCan = tutoriasSemana.filter(t => estadoDe(t) === 'Cancelada').length;
const totSinTutor = tutoriasSemana.filter(t => sinTutor(t) && estadoDe(t) === 'Solicitada').length;
const tutoresActivos = tutores.filter(t => String(t.estado) === 'Activo').length;
const valorGeneral = calificaciones.length ? (calificaciones.reduce((a, c) => a + Number(c.valoracion || 0), 0) / calificaciones.length).toFixed(2) : 'N/A';

const porMateria = materias.map(m => {
  const ts = tutoriasSemana.filter(x => String(x.id_materia) === String(m.id_materia));
  return { nombre: m.nombre || m.nombre_materia || m.materia || '', total: ts.length, finalizadas: ts.filter(x => estadoDe(x) === 'Finalizada').length, canceladas: ts.filter(x => estadoDe(x) === 'Cancelada').length, sinTutor: ts.filter(x => sinTutor(x)).length };
}).filter(m => m.total > 0);

const alertas = [];
for (const t of porTutor) {
  if (t.canceladas >= 3) alertas.push('⚠️ Tutor ' + t.nombre + ' con ' + t.canceladas + ' cancelaciones' + (esManual ? '' : ' esta semana'));
  if (t.prom !== null && t.prom < 3.5) alertas.push('⚠️ Tutor ' + t.nombre + ' con valoración baja (' + t.prom.toFixed(2) + ')');
  if (t.prom !== null && t.prom >= 4.5) alertas.push('🌟 Tutor destacado: ' + t.nombre + ' (' + t.prom.toFixed(2) + ')');
}
for (const m of porMateria) {
  const tutoresMateria = tutores.filter(t => String(t.materias || '').toLowerCase().includes(m.nombre.toLowerCase()) && String(t.estado) === 'Activo').length;
  if (m.total >= 3 && tutoresMateria <= 1) alertas.push('⚠️ Materia ' + m.nombre + ' con alta demanda (' + m.total + ') y pocos tutores (' + tutoresMateria + ')');
  if (m.sinTutor > 0) alertas.push('⚠️ Materia ' + m.nombre + ' con ' + m.sinTutor + ' solicitudes sin tutor');
}
if (totSinTutor > 0) alertas.push('⚠️ ' + totSinTutor + ' solicitudes sin tutor asignado');

const estiloTabla = 'border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px;width:100%"';
const th = 'style="background:#e8e8e8;padding:6px"';

let filasTutor = '';
for (const t of porTutor) { filasTutor += '<tr><td>' + t.nombre + '</td><td>' + t.materias + '</td><td>' + t.solicitadas + '</td><td>' + t.asignadas + '</td><td>' + t.enCurso + '</td><td>' + t.finalizadas + '</td><td>' + t.canceladas + '</td><td>' + fmtProm(t.prom) + '</td><td>' + t.total + '</td></tr>' + LF; }
if (!filasTutor) filasTutor = '<tr><td colspan="9">Sin actividad de tutores</td></tr>';

let filasRanking = '';
ranking.forEach((t, i) => { filasRanking += '<tr><td>' + (i + 1) + '</td><td>' + t.nombre + '</td><td>' + fmtProm(t.prom) + '</td><td>' + t.finalizadas + '</td><td>' + t.canceladas + '</td></tr>' + LF; });
if (!filasRanking) filasRanking = '<tr><td colspan="5">Sin datos</td></tr>';

let filasMateria = '';
for (const m of porMateria) { filasMateria += '<tr><td>' + m.nombre + '</td><td>' + m.total + '</td><td>' + m.finalizadas + '</td><td>' + m.canceladas + '</td><td>' + m.sinTutor + '</td></tr>' + LF; }
if (!filasMateria) filasMateria = '<tr><td colspan="5">Sin demanda registrada</td></tr>';

let listaAlertas = '';
if (alertas.length === 0) listaAlertas = '<li>✅ Sin alertas</li>';
for (const a of alertas) listaAlertas += '<li>' + a + '</li>' + LF;

const html = '<html><body style="font-family:Arial,sans-serif;color:#333;max-width:900px">'
  + '<h2>📊 TutorBot — ' + tituloReporte + '</h2>'
  + '<p>' + subtituloPeriodo + '</p>'
  + '<h3>1. Resumen general</h3><ul>'
  + '<li>Total solicitudes: ' + totalSol + '</li>'
  + '<li>Asignadas: ' + totAsig + ' &nbsp;|&nbsp; En curso: ' + totEnCurso + ' &nbsp;|&nbsp; Finalizadas: ' + totFin + ' &nbsp;|&nbsp; Canceladas: ' + totCan + '</li>'
  + '<li>Solicitudes sin tutor: ' + totSinTutor + '</li>'
  + '<li>Tutores activos: ' + tutoresActivos + '</li>'
  + '<li>Valoración general: ' + valorGeneral + '</li>'
  + '</ul>'
  + '<h3>2. Indicadores por tutor</h3>'
  + '<table ' + estiloTabla + '><thead><tr><th ' + th + '>Tutor</th><th ' + th + '>Materias</th><th ' + th + '>Solicitadas</th><th ' + th + '>Asignadas</th><th ' + th + '>En curso</th><th ' + th + '>Finalizadas</th><th ' + th + '>Canceladas</th><th ' + th + '>Valoración prom.</th><th ' + th + '>Total</th></tr></thead><tbody>' + filasTutor + '</tbody></table>'
  + '<h3>3. Ranking de tutores</h3>'
  + '<table ' + estiloTabla + '><thead><tr><th ' + th + '>#</th><th ' + th + '>Tutor</th><th ' + th + '>Valoración</th><th ' + th + '>Finalizadas</th><th ' + th + '>Canceladas</th></tr></thead><tbody>' + filasRanking + '</tbody></table>'
  + '<h3>4. Demanda por materia</h3>'
  + '<table ' + estiloTabla + '><thead><tr><th ' + th + '>Materia</th><th ' + th + '>Solicitudes</th><th ' + th + '>Finalizadas</th><th ' + th + '>Canceladas</th><th ' + th + '>Sin tutor</th></tr></thead><tbody>' + filasMateria + '</tbody></table>'
  + '<h3>5. Alertas administrativas</h3><ul>' + listaAlertas + '</ul>'
  + '</body></html>';

return [{ json: { html, total: totalSol, subject: 'TutorBot - ' + tituloReporte + ' ' + inicioSemana.toFormat('dd/MM/yyyy') } }];
